/* ═══════════════════════════════════════════════════════
   NeuroSpect v2 — Design System
   Gradient-rich modern SaaS · Electric blue + gold
   Dashboard layout · Orbitron headings
   ═══════════════════════════════════════════════════════ */
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;600;700;800;900&family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root{
  --blue-400:#60a5fa;--blue-500:#3b82f6;--blue-600:#2563eb;--blue-700:#1d4ed8;--blue-800:#1e40af;--blue-900:#1e3a5f;
  --gold-300:#fcd34d;--gold-400:#fbbf24;--gold-500:#f59e0b;--gold-600:#d97706;
  --bg-0:#050810;--bg-1:#0a0f1a;--bg-2:#0f1629;--bg-3:#141c36;
  --surface:rgba(15,22,41,0.7);--surface-hover:rgba(20,28,54,0.85);
  --border:rgba(59,130,246,0.12);--border-hover:rgba(59,130,246,0.28);--border-gold:rgba(251,191,36,0.2);
  --text-h:#f0f4ff;--text-b:#b8c9e0;--text-m:#7a8fad;--text-d:#4a5f7a;
  --font-h:'Orbitron',system-ui,sans-serif;--font-b:'Inter',system-ui,sans-serif;--font-m:'JetBrains Mono','Fira Code',monospace;
  --sidebar-w:240px;
  --radius:14px;
}

html{scroll-behavior:smooth;-webkit-font-smoothing:antialiased}
body{font-family:var(--font-b);background:var(--bg-0);color:var(--text-b);line-height:1.6;overflow-x:hidden}
::selection{background:rgba(59,130,246,0.3);color:#fff}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none}

/* ── Typography ── */
h1,h2,h3,h4{font-family:var(--font-h);color:var(--text-h);line-height:1.1;font-weight:700}
h1{font-size:clamp(1.8rem,3.5vw,2.8rem);letter-spacing:0.04em;text-transform:uppercase}
h2{font-size:clamp(1.4rem,2.5vw,2rem);letter-spacing:0.03em}
h3{font-size:1rem;letter-spacing:0.02em}
.grad-text{background:linear-gradient(135deg,var(--blue-400),var(--gold-400));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.grad-text-blue{background:linear-gradient(135deg,var(--blue-400),#a78bfa);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.label{font-family:var(--font-m);font-size:0.65rem;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:var(--blue-400)}
.mono{font-family:var(--font-m)}

/* ── Dashboard Shell ── */
.shell{display:flex;min-height:100vh}

/* Sidebar */
.side{position:fixed;top:0;left:0;width:var(--sidebar-w);height:100vh;display:flex;flex-direction:column;
  background:linear-gradient(180deg,rgba(10,15,26,0.95),rgba(5,8,16,0.98));
  border-right:1px solid var(--border);z-index:100;overflow-y:auto;overflow-x:hidden}
.side-logo{padding:1.25rem 1.25rem 1rem;display:flex;align-items:center;gap:0.6rem}
.side-logo-mark{width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,var(--blue-500),var(--blue-700));
  display:flex;align-items:center;justify-content:center;color:#fff;font-family:var(--font-h);font-weight:800;font-size:0.95rem;
  box-shadow:0 0 20px rgba(59,130,246,0.3),inset 0 1px 0 rgba(255,255,255,0.15)}
.side-logo-text{font-family:var(--font-h);font-weight:700;font-size:0.8rem;letter-spacing:0.06em;text-transform:uppercase;
  background:linear-gradient(90deg,#e0ecff,var(--blue-400));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
  filter:drop-shadow(0 0 6px rgba(59,130,246,0.25))}

.side-nav{flex:1;padding:0.5rem 0.75rem;display:flex;flex-direction:column;gap:2px}
.side-link{display:flex;align-items:center;gap:0.65rem;padding:0.6rem 0.75rem;border-radius:10px;font-size:0.82rem;font-weight:500;
  color:var(--text-m);transition:all 0.2s;position:relative}
.side-link:hover{color:var(--text-b);background:rgba(59,130,246,0.06)}
.side-link.active{color:var(--blue-400);background:rgba(59,130,246,0.1);font-weight:600}
.side-link.active::before{content:'';position:absolute;left:0;top:25%;height:50%;width:3px;border-radius:0 3px 3px 0;background:var(--blue-500);box-shadow:0 0 8px rgba(59,130,246,0.4)}
.side-link svg{width:18px;height:18px;opacity:0.6;flex-shrink:0}
.side-link.active svg{opacity:1}

.side-section{font-family:var(--font-m);font-size:0.58rem;letter-spacing:0.1em;text-transform:uppercase;color:var(--text-d);
  padding:1.25rem 0.75rem 0.4rem;margin-top:0.25rem}

.side-bottom{padding:1rem;border-top:1px solid var(--border)}
.side-cta{display:flex;align-items:center;justify-content:center;gap:0.5rem;width:100%;padding:0.65rem;border-radius:10px;
  background:linear-gradient(135deg,var(--blue-600),var(--blue-500));color:#fff;font-weight:600;font-size:0.8rem;
  font-family:var(--font-h);letter-spacing:0.04em;text-transform:uppercase;transition:all 0.25s;
  box-shadow:0 4px 16px rgba(59,130,246,0.25)}
.side-cta:hover{box-shadow:0 4px 24px rgba(59,130,246,0.4);transform:translateY(-1px)}

/* Main content */
.main{margin-left:var(--sidebar-w);flex:1;min-height:100vh;position:relative}
.page{padding:2rem clamp(1.5rem,3vw,2.5rem) 4rem}
.page-header{margin-bottom:2rem}

/* ── Cards ── */
.card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:1.25rem;
  position:relative;backdrop-filter:blur(12px);transition:all 0.35s cubic-bezier(0.16,1,0.3,1);overflow:hidden}
.card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;

/* ═══ PRICING ═══ */
function PricingPage() {
  return (
    <div className="page">
      <Rv>
        <div className="hero-grad" style={{ padding: 'clamp(2rem,4vw,3rem)', marginBottom: '1.5rem' }}>
          <h1 style={{ marginBottom: 10 }}>Grow Into Your <span className="grad-text">Edge</span></h1>
          <p style={{ fontSize: '0.92rem', color: 'var(--text-m)', maxWidth: 520, lineHeight: 1.65 }}>Start free. Upgrade as your trading evolves.</p>
        </div>
      </Rv>
      <Rv delay={60}>
        <div className="bento bento-3">
          {PRICING_TIERS.map(function(t, i) {
            return (
              <Rv key={t.name} delay={i * 40}>
                <div className={'card ' + (t.highlight ? 'card-active' : '')} style={{ height: '100%', display: 'flex', flexDirection: 'column', position: 'relative' }}>
                  {t.highlight && <div style={{ position: 'absolute', top: -10, left: '50%', transform: 'translateX(-50%)' }}><span className="badge badge-blue" style={{ fontSize: '0.55rem', background: 'var(--blue-500)', color: '#fff', border: 'none', fontWeight: 700 }}>Most Popular</span></div>}
                  <h3 style={{ fontSize: '1rem', marginBottom: 2 }}>{t.name}</h3>
                  <p style={{ fontSize: '0.7rem', color: 'var(--text-d)', marginBottom: 12 }}>{t.target}</p>
                  <div style={{ display: 'flex', alignItems: 'baseline', gap: 3, marginBottom: 14 }}>
                    <span style={{ fontSize: '2rem', fontWeight: 800, color: 'var(--text-h)', fontFamily: 'var(--font-h)' }}>${t.price}</span>
                    <span style={{ fontSize: '0.78rem', color: 'var(--text-d)' }}>{t.period}</span>
                  </div>
                  <button className={'btn btn-sm ' + (t.highlight ? 'btn-blue' : 'btn-ghost')} style={{ width: '100%', marginBottom: 14 }}>
                    {t.price === '0' ? 'Get Started' : 'Join Waitlist'}
                  </button>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6, flex: 1 }}>
                    {t.features.map(function(f) {
                      return <div key={f} style={{ display: 'flex', alignItems: 'flex-start', gap: 6, fontSize: '0.75rem' }}>
                        <span style={{ color: t.highlight ? 'var(--blue-400)' : 'var(--text-d)', flexShrink: 0, marginTop: 1 }}>✓</span>
                        <span style={{ color: 'var(--text-m)' }}>{f}</span>
                      </div>;
                    })}
                  </div>
                </div>
              </Rv>
            );
          })}
        </div>
      </Rv>
      <Rv delay={200}>
        <div className="card card-gold" style={{ textAlign: 'center', padding: '1.5rem', marginTop: '1.5rem' }}>
          <p style={{ fontSize: '0.75rem', color: 'var(--text-d)' }}>NeuroSpect is an educational tool. Not financial advice. Past performance does not guarantee future results. Trading involves risk of loss.</p>
        </div>
      </Rv>
    </div>
  );
}

window.FeaturesPage = FeaturesPage;
window.PerformancePage = PerformancePage;
window.ArchitecturePage = ArchitecturePage;
window.ComparePage = ComparePage;
window.PricingPage = PricingPage;

