/* NeuroSpect v2 — Live Trading Simulator Page */

/* ── Candle Chart SVG (shared with SimulatorSection in ns-simulator.jsx) ── */
function SimChartV2({ candles, visibleCount, tierEntries, width, height }) {
  var w = width || 700, h = height || 260;
  var pad = { t: 12, r: 48, b: 20, l: 12 };
  var cw = (w - pad.l - pad.r) / candles.length;
  var visible = candles.slice(0, visibleCount);
  var allP = candles.flatMap(function(c) { return [c.h, c.l]; });
  var minP = Math.min.apply(null, allP) - 5;
  var maxP = Math.max.apply(null, allP) + 5;
  var range = maxP - minP;
  var yp = function(p) { return pad.t + ((maxP - p) / range) * (h - pad.t - pad.b); };
  var xp = function(i) { return pad.l + i * cw; };

  var fvgs = [
    { y1: 18355, y2: 18310, label: 'FVG', color: 'rgba(6,182,212,0.06)' },
    { y1: 18420, y2: 18395, label: 'OB', color: 'rgba(139,92,246,0.05)' },
  ];

  var ticks = [];
  var step = Math.ceil(range / 5 / 10) * 10;
  for (var p = Math.ceil(minP / step) * step; p <= maxP; p += step) ticks.push(p);

  return (
    <svg viewBox={'0 0 ' + w + ' ' + h} style={{ width: '100%', height: '100%' }}>
      {ticks.map(function(t) {
        return (
          <g key={t}>
            <line x1={pad.l} x2={w - pad.r} y1={yp(t)} y2={yp(t)} stroke="rgba(255,255,255,0.04)" strokeWidth="0.5" />
            <text x={w - pad.r + 4} y={yp(t) + 3} fill="rgba(255,255,255,0.2)" fontSize="8" fontFamily="var(--font-m)">{t.toLocaleString()}</text>
          </g>
        );
      })}
      {fvgs.map(function(f, i) {
        return (
          <g key={i}>
            <rect x={pad.l} y={yp(f.y1)} width={w - pad.l - pad.r} height={yp(f.y2) - yp(f.y1)} fill={f.color} rx="2" />
            <text x={pad.l + 4} y={yp(f.y1) + 10} fill="rgba(6,182,212,0.25)" fontSize="7" fontFamily="var(--font-m)">{f.label}</text>
          </g>
        );
      })}
      {visible.map(function(c, i) {
        var bull = c.c >= c.o;
        var color = bull ? '#10b981' : '#ef4444';
        var bx = xp(i) + cw * 0.2;
        var bw = cw * 0.6;
        var bodyTop = yp(Math.max(c.o, c.c));
        var bodyH = Math.max(yp(Math.min(c.o, c.c)) - bodyTop, 1);
        return (
          <g key={i}>
            <line x1={xp(i) + cw / 2} x2={xp(i) + cw / 2} y1={yp(c.h)} y2={yp(c.l)} stroke={color} strokeWidth="1" strokeOpacity="0.5" />
            <rect x={bx} y={bodyTop} width={bw} height={bodyH} fill={color} fillOpacity={0.8} rx="0.5" />
          </g>
        );
      })}
      {tierEntries.filter(function(e) { return e.candle < visibleCount; }).map(function(e, i) {
        return (
          <g key={i}>
            <line x1={xp(e.candle) + cw / 2} x2={xp(e.candle) + cw / 2} y1={yp(e.price) - 12} y2={yp(e.price)} stroke={e.color} strokeWidth="1" strokeDasharray="2 2" strokeOpacity="0.5" />
            <circle cx={xp(e.candle) + cw / 2} cy={yp(e.price)} r="3.5" fill={e.color} fillOpacity="0.9">
              <animate attributeName="r" values="3;4;3" dur="2s" repeatCount="indefinite" />
            </circle>
            <text x={xp(e.candle) + cw / 2} y={yp(e.price) - 15} fill={e.color} fontSize="6" fontFamily="var(--font-m)" textAnchor="middle" opacity="0.7">{e.tier}</text>
          </g>
        );
      })}
      {visibleCount > 0 && visible[visibleCount - 1] && (
        <line x1={xp(visibleCount - 1) + cw / 2} x2={w - pad.r} y1={yp(visible[visibleCount - 1].c)} y2={yp(visible[visibleCount - 1].c)} stroke="rgba(255,255,255,0.15)" strokeWidth="0.5" strokeDasharray="3 3" />
      )}
    </svg>
  );
}

/* ── Simulator Page ── */
function SimulatorPage() {
  var runningState = React.useState(false);
  var running = runningState[0], setRunning = runningState[1];
  var candleState = React.useState(0);
  var candleIdx = candleState[0], setCandleIdx = candleState[1];
  var speedState = React.useState(1);
  var speed = speedState[0], setSpeed = speedState[1];
  var intervalRef = React.useRef(null);

  var totalCandles = NQ_CANDLES.length;

  function startSim() {
    setRunning(true);
    setCandleIdx(0);
  }

  React.useEffect(function() {
    if (!running) return;
    if (candleIdx >= totalCandles) { setRunning(false); return; }
    var ms = [800, 400, 160][speed - 1] || 800;
    intervalRef.current = setTimeout(function() { setCandleIdx(function(c) { return c + 1; }); }, ms);
    return function() { clearTimeout(intervalRef.current); };
  }, [running, candleIdx, speed]);

  var visibleCount = (running || candleIdx > 0) ? candleIdx : totalCandles;
  var progress = visibleCount / totalCandles;

  var tierEntries = [
    { candle: 5, price: 18295, tier: 'T1', color: '#64748b' },
    { candle: 5, price: 18305, tier: 'T3', color: '#06b6d4' },
    { candle: 5, price: 18300, tier: 'T4', color: '#10b981' },
    { candle: 10, price: 18390, tier: 'T1', color: '#64748b' },
    { candle: 10, price: 18385, tier: 'T2', color: '#8b5cf6' },
    { candle: 17, price: 18418, tier: 'T3', color: '#06b6d4' },
    { candle: 17, price: 18420, tier: 'T4', color: '#10b981' },
  ];

  var tierStates = [
    { id: 'tier1', status: progress > 0.2 ? 'Trading' : 'Watching',
      pnl: Math.round(progress * 1850), trades: Math.round(progress * 3), winRate: '42%',
      reasoning: progress > 0.3 ? 'Entered short at FVG — no HTF confirmation. Stop hit.' : 'Watching for displacement...' },
    { id: 'tier2', status: progress > 0.3 ? 'Trading' : 'Filtering',
      pnl: Math.round(progress * 4900), trades: Math.round(progress * 2), winRate: '55%',
      reasoning: progress > 0.3 ? 'Volume filter passed. Model entered at FVG midpoint. Standard size.' : 'Running statistical filters...' },
    { id: 'tier3', status: progress > 0.2 ? 'Trading' : 'Grading',
      pnl: Math.round(progress * 7450), trades: Math.round(progress * 2), winRate: '62%',
      reasoning: progress > 0.3 ? 'NSLM graded A+ — full size entry at FVG discount. 2R target.' : 'NSLM evaluating setup quality...' },
    { id: 'tier4', status: progress > 0.2 ? 'Trading' : 'Analyzing',
      pnl: Math.round(progress * 10900), trades: Math.round(progress * 1.5), winRate: '71%',
      reasoning: progress > 0.3 ? 'Full confluence confirmed. 1.5x size. Partials at 1.5R and 2R.' : 'Full confluence scan running...' },
  ];

  var tradeLog = [
    { time: '10:02', tier: 'tier1', action: 'SHORT entry', entry: '18,295', pnl: -280 },
    { time: '10:05', tier: 'tier3', action: 'SHORT entry', entry: '18,305', pnl: 480 },
    { time: '10:05', tier: 'tier4', action: 'SHORT entry', entry: '18,300', pnl: 560 },
    { time: '10:32', tier: 'tier1', action: 'LONG entry', entry: '18,390', pnl: 800 },
    { time: '10:34', tier: 'tier2', action: 'LONG entry', entry: '18,385', pnl: 460 },
    { time: '11:15', tier: 'tier4', action: 'LONG entry', entry: '18,420', pnl: 700 },
  ];
  var visibleLogs = tradeLog.filter(function(_, i) { return progress > (i + 1) / (tradeLog.length + 2); });

  return (
    <div className="page">
      {/* Hero */}
      <Rv>
        <div className="hero-grad" style={{ padding: 'clamp(2rem,4vw,3rem)', marginBottom: '1.5rem' }}>
          <span className="badge badge-blue" style={{ marginBottom: 14 }}><span className="badge-dot" style={{ background: '#06b6d4' }}></span>Flagship Demo</span>
          <h1 style={{ marginBottom: 10 }}>Watch Four Traders. <span className="grad-text">Same Market.</span></h1>
          <p style={{ fontSize: '0.92rem', color: 'var(--text-m)', maxWidth: 540, lineHeight: 1.65, marginBottom: 8 }}>
            Same NQ session. Four tiers of intelligence. See how discretionary, quant, hybrid, and sovereign approaches diverge on identical price action.
          </p>
          <p style={{ fontSize: '0.75rem', color: 'var(--text-d)', maxWidth: 480, lineHeight: 1.5 }}>
            Simulation uses synthetic data for illustration only. Past performance does not guarantee future results. Not financial advice.
          </p>
        </div>
      </Rv>

      {/* Sim card */}
      <Rv delay={60}>
