/* NeuroSpect v2 — Live Trading Simulator Page */

/* ── Candle Chart SVG (shared with SimulatorSection in ns-simulator.jsx) ── */
function SimChartV2({ candles, visibleCount, tierEntries, width, height }) {
  var w = width || 700, h = height || 260;
  var pad = { t: 12, r: 48, b: 20, l: 12 };
  var cw = (w - pad.l - pad.r) / candles.length;
  var visible = candles.slice(0, visibleCount);
  var allP = candles.flatMap(function(c) { return [c.h, c.l]; });
  var minP = Math.min.apply(null, allP) - 5;
  var maxP = Math.max.apply(null, allP) + 5;
  var range = maxP - minP;
  var yp = function(p) { return pad.t + ((maxP - p) / range) * (h - pad.t - pad.b); };
  var xp = function(i) { return pad.l + i * cw; };

  var fvgs = [
    { y1: 18355, y2: 18310, label: 'FVG', color: 'rgba(6,182,212,0.06)' },
    { y1: 18420, y2: 18395, label: 'OB', color: 'rgba(139,92,246,0.05)' },
  ];

  var ticks = [];
  var step = Math.ceil(range / 5 / 10) * 10;
  for (var p = Math.ceil(minP / step) * step; p <= maxP; p += step) ticks.push(p);

  return (
    <svg viewBox={'0 0 ' + w + ' ' + h} style={{ width: '100%', height: '100%' }}>
      {ticks.map(function(t) {
        return (
          <g key={t}>
            <line x1={pad.l} x2={w - pad.r} y1={yp(t)} y2={yp(t)} stroke="rgba(255,255,255,0.04)" strokeWidth="0.5" />
            <text x={w - pad.r + 4} y={yp(t) + 3} fill="rgba(255,255,255,0.2)" fontSize="8" fontFamily="var(--font-m)">{t.toLocaleString()}</text>
          </g>
        );
      })}
      {fvgs.map(function(f, i) {
        return (
          <g key={i}>
            <rect x={pad.l} y={yp(f.y1)} width={w - pad.l - pad.r} height={yp(f.y2) - yp(f.y1)} fill={f.color} rx="2" />
            <text x={pad.l + 4} y={yp(f.y1) + 10} fill="rgba(6,182,212,0.25)" fontSize="7" fontFamily="var(--font-m)">{f.label}</text>
          </g>
        );
      })}
      {visible.map(function(c, i) {
        var bull = c.c >= c.o;
        var color = bull ? '#10b981' : '#ef4444';
        var bx = xp(i) + cw * 0.2;
        var bw = cw * 0.6;
        var bodyTop = yp(Math.max(c.o, c.c));
        var bodyH = Math.max(yp(Math.min(c.o, c.c)) - bodyTop, 1);
        return (
          <g key={i}>
            <line x1={xp(i) + cw / 2} x2={xp(i) + cw / 2} y1={yp(c.h)} y2={yp(c.l)} stroke={color} strokeWidth="1" strokeOpacity="0.5" />
            <rect x={bx} y={bodyTop} width={bw} height={bodyH} fill={color} fillOpacity={0.8} rx="0.5" />
          </g>
        );
      })}
      {tierEntries.filter(function(e) { return e.candle < visibleCount; }).map(function(e, i) {
        return (
          <g key={i}>
            <line x1={xp(e.candle) + cw / 2} x2={xp(e.candle) + cw / 2} y1={yp(e.price) - 12} y2={yp(e.price)} stroke={e.color} strokeWidth="1" strokeDasharray="2 2" strokeOpacity="0.5" />
            <circle cx={xp(e.candle) + cw / 2} cy={yp(e.price)} r="3.5" fill={e.color} fillOpacity="0.9">
              <animate attributeName="r" values="3;4;3" dur="2s" repeatCount="indefinite" />
            </circle>
            <text x={xp(e.candle) + cw / 2} y={yp(e.price) - 15} fill={e.color} fontSize="6" fontFamily="var(--font-m)" textAnchor="middle" opacity="0.7">{e.tier}</text>
          </g>
        );
      })}
      {visibleCount > 0 && visible[visibleCount - 1] && (
        <line x1={xp(visibleCount - 1) + cw / 2} x2={w - pad.r} y1={yp(visible[visibleCount - 1].c)} y2={yp(visible[visibleCount - 1].c)} stroke="rgba(255,255,255,0.15)" strokeWidth="0.5" strokeDasharray="3 3" />
      )}
    </svg>
  );
}

/* ── Simulator Page ── */
function SimulatorPage() {
  var runningState = React.useState(false);
  var running = runningState[0], setRunning = runningState[1];
  var candleState = React.useState(0);
